questions.solution:
function arithmeticTerm(first, difference, n) {
  return first + n * difference;
}

function geometricTerm(first, ratio, n) {
  return first * ratio ** n;
}

console.log(arithmeticTerm(4500, -150, 10));
console.log(geometricTerm(500, 2, 10));

