const first = 10000;
const step = 2000;
const count = 10;

let total = 0;
for (let i = 0; i < count; i++) {
  total = total + (first + i * step);
}
console.log(total);

const last = first + (count - 1) * step;
console.log(count * (first + last) / 2);

