questions.solution:
function compound(principal, rate, periods) {
  let balance = principal;
  for (let i = 0; i < periods; i++) {
    balance = balance * (1 + rate);
  }
  return balance;
}

console.log(Math.round(compound(500000, 0.12, 5)), Math.round(500000 * 1.12 ** 5));

