function canRepay(owedKobo, rateBasisPoints, paymentKobo) {
  const interest = Math.round(owedKobo * rateBasisPoints / 10000);
  return paymentKobo > interest;
}

console.log(canRepay(10000000, 500, 400000));
console.log(canRepay(10000000, 500, 500000));
console.log(canRepay(10000000, 500, 1500000));

